        { "name": "Dip (Horticulture)", "aps": 25, "duration": "3 years", "description": "Prepares horticulturists, maintenance managers, site managers or grounds superintendents, researchers (developing new cultivars or solving problems) and academics. Offered at Pretoria Campus. Note: APS 25 with Mathematics or Technical Mathematics; APS 26 with Mathematical Literacy. Jobs: Horticulturist (R14 000–R55 000/month); Site Manager (R18 000–R65 000/month); Grounds Superintendent (R18 000–R65 000/month); Researcher (R20 000–R80 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 50 }, { "subject": "Life Sciences OR Physical Sciences OR Technical Sciences", "minPercent": 40 } ] },
        { "name": "Dip (Landscape Technology)", "aps": 25, "duration": "3 years", "description": "Prepares landscape consultants, landscape designers or landscape contractors, site managers, maintenance managers, nursery managers, researchers (developing new cultivars or solving problems) and academics. Offered at Pretoria Campus. Note: APS 25 with Mathematics or Technical Mathematics; APS 26 with Mathematical Literacy. Jobs: Landscape Consultant (R18 000–R70 000/month); Landscape Designer (R16 000–R60 000/month); Site Manager (R18 000–R65 000/month); Nursery Manager (R15 000–R60 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 50 }, { "subject": "Life Sciences OR Physical Sciences OR Technical Sciences", "minPercent": 40 } ] },
        { "name": "Dip (Nature Conservation)", "aps": 24, "duration": "3 years", "description": "Prepares conservation managers, conservation researchers, environmental educationists, eco-destination planners, guides, nature conservators and hunting operators. Recommended subjects: Agricultural Sciences, Geography, Life Sciences, Physical Sciences or Technical Sciences. Offered at Pretoria Campus. Note: APS 24 with Mathematics or Technical Mathematics; APS 25 with Mathematical Literacy. Jobs: Conservation Manager (R16 000–R60 000/month); Conservation Researcher (R18 000–R68 000/month); Environmental Educationist (R14 000–R48 000/month); Nature Conservator (R14 000–R45 000/month); Hunting Operator (R15 000–R55 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 50 } ] },
        { "name": "Dip (Wildlife Management)", "aps": 24, "duration": "3 years", "description": "Prepares game-farm or ranch managers, wildlife advisers, professional hunters, disease-control specialists, habitat management professionals and game population dynamics specialists including game capture and translocation. Recommended subjects: Agricultural Sciences, Geography, Life Sciences, Physical Sciences or Technical Sciences. Offered at Pretoria Campus. Note: APS 24 with Mathematics or Technical Mathematics; APS 25 with Mathematical Literacy. Jobs: Game Farm Manager (R16 000–R60 000/month); Wildlife Adviser (R16 000–R58 000/month); Professional Hunter (R15 000–R55 000/month); Game Capture Specialist (R16 000–R55 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 50 } ] },
        { "name": "HCert (Forestry Management) (Only Mbombela Campus)", "aps": 18, "duration": "2 years", "description": "Entry-level qualification. Offered at Mbombela Campus only. Note: APS 18 with Mathematics or Technical Mathematics; APS 21 with Mathematical Literacy. Jobs: Forestry Technician (R12 000–R42 000/month); Forestry Supervisor (R14 000–R45 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 40 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 40 } ] },
        { "name": "BEnvHealth", "aps": 24, "duration": "4 years", "description": "Prepares environmental health practitioners, health advisers, air-pollution control officers, meat inspectors, occupational hygienists, consultants, inspectors, environmental officers/auditors, food safety auditors, risk officers and researchers. Offered at Pretoria Campus. Jobs: Environmental Health Practitioner (R18 000–R55 000/month); Occupational Hygienist (R18 000–R60 000/month); Food Safety Auditor (R18 000–R70 000/month); Environmental Consultant (R18 000–R70 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 }, { "subject": "Two other subjects", "minPercent": 50 } ] },
        { "name": "BNursing", "aps": 27, "duration": "4 years", "description": "Prepares graduates to practice as nurse and midwife in public and private health care facilities or as private nurse practitioners. Offered at Pretoria Campus. Registration with the SANC is required. Jobs: Professional Nurse (R18 000–R67 000/month); Midwife (R20 000–R70 000/month); Private Nurse Practitioner (variable).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "BPharm / Bachelor of Pharmacy", "aps": 24, "duration": "4 years", "description": "Prepares pharmacists. Offered at Arcadia Campus. Registration with the SAPC is required. Jobs: Pharmacist (R25 000–R90 000/month); Clinical Pharmacist (R28 000–R100 000/month); Industrial Pharmacist (R30 000–R105 000/month); Hospital Pharmacist (R26 000–R92 000/month); Regulatory Affairs Pharmacist (R28 000–R98 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 }, { "subject": "Two other subjects", "minPercent": 50 } ] },
        { "name": "BRad (Diagnostic) / Bachelor of Radiography in Diagnostics", "aps": 24, "duration": "4 years", "description": "Prepares radiographers, radiation control officers and medical and pharmaceutical representatives. Offered at Arcadia Campus. Registration with the HPCSA is required. Jobs: Diagnostic Radiographer (R22 000–R75 000/month); Radiation Control Officer (R22 000–R78 000/month); Medical and Pharmaceutical Representative (R18 000–R65 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "BHSci (Biokinetics)", "aps": 24, "duration": "4 years", "description": "Prepares graduates for employment in a number of allied health-related fields. The scope of occupation is primarily dependent on the entrepreneurial initiative of the individual, including practising as a Biokineticist in corporate sector, correctional facilities, elite and professional sport, fire services, industry, local authorities, military bases, military hospitals, police services and private practices. Offered at Pretoria Campus. Jobs: Biokineticist (R16 000–R60 000/month); Rehabilitation Specialist (R17 000–R65 000/month); Sports Rehabilitation Therapist (R16 000–R58 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "BHSci (Clinical Technology)", "aps": 24, "duration": "4 years", "description": "Prepares clinical technologists for private hospitals and private practices, with opportunities in cardiology, nephrology, reproduction, the respiratory system and neurophysiology, cardiovascular perfusion and pulmonology. Offered at Arcadia Campus. Registration with the HPCSA is required. Jobs: Clinical Technologist (R28 000–R95 000/month); Cardiology Technologist (R28 000–R95 000/month); Nephrology Technologist (R25 000–R85 000/month); Pulmonology Technologist (R25 000–R85 000/month); Cardiovascular Perfusion Technologist (R28 000–R95 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "BHSci (Medical Laboratory Science)", "aps": 24, "duration": "4 years", "description": "Prepares medical technologists to work in medical field, analysing human tissue and blood pathology, histology, virology, blood transfusion and laboratory work. Offered at Arcadia Campus. Registration with the HPCSA is required. Jobs: Medical Laboratory Scientist (R20 000–R70 000/month); Medical Technologist (R20 000–R70 000/month); Laboratory Technologist (R18 000–R60 000/month); Pathology Lab Supervisor (R28 000–R85 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "BHSci (Medical Orthotics and Prosthetics)", "aps": 24, "duration": "4 years", "description": "Prepares medical orthotists or prosthetists, graduates for own practice, medical representatives (orthopaedic rehabilitation) by assessing, measuring, designing, manufacturing, maintaining and fitting orthoses and prostheses. Offered at Pretoria Campus. Registration with the HPCSA is required. Jobs: Medical Orthotist and Prosthetist (R25 000–R85 000/month); Private Practice Owner (variable); Medical Representative (Orthopaedic Rehabilitation) (R18 000–R65 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "BHSci (Veterinary Technology)", "aps": 24, "duration": "4 years", "description": "Prepares veterinary technologists (activities include the collection and processing of samples, diagnostic work and research and vaccine production). Offered at Arcadia Campus. Registration with the SAVC is required. Jobs: Veterinary Technologist (R20 000–R70 000/month); Veterinary Nurse (R16 000–R60 000/month); Research Assistant (R14 000–R45 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences OR Agricultural Sciences", "minPercent": 50 } ] },
        { "name": "Dip (Kinesiology and Coaching Science)", "aps": 24, "duration": "3 years", "description": "Prepares sports scientists, sports coaches, sports managers and sports researchers. Qualified students will function at a level to cater for the needs of an apparently healthy population, as well as fitness training for special populations such as children, the youth and older adults. This qualification also offers a physical activity foundation based on scientific knowledge to facilitate health and sport in order to support health workers, as well as enhancing the level of professionalism within the national sport, health and fitness industry. Offered at Pretoria Campus. Jobs: Sports Scientist (R15 000–R55 000/month); Sports Coach (R12 000–R45 000/month); Sports Manager (R18 000–R70 000/month); Sports Researcher (R18 000–R70 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 40 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 40 }, { "subject": "Life Sciences", "minPercent": 40 } ] },
        { "name": "Dip (Somatic Therapy)", "aps": 22, "duration": "3 years", "description": "Prepares health and skin care professionals as somatologists, aromatherapists, reflexologists, stress-relief and relaxation therapists at health spas or stress clinics, representatives of cosmetic firms or own business. Offered at Arcadia Campus. Note: APS 22 with Mathematics or Technical Mathematics; APS 23 with Mathematical Literacy. Jobs: Somatologist (R14 000–R55 000/month); Aromatherapist (R14 000–R52 000/month); Reflexologist (R14 000–R50 000/month); Spa Therapist (R12 000–R45 000/month); Cosmetic Firm Representative (R14 000–R50 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 50 } ] },
        { "name": "HCert (Dental Assisting)", "aps": 20, "duration": "1 year", "description": "Prepares graduates for assisting in a dental practice, assisting a dentist, infection control, stock control and accounts. Offered at Pretoria Campus. Registration with the HPCSA is required. Jobs: Dental Assistant (R12 000–R42 000/month); Dental Practice Assistant (R14 000–R48 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Mathematical Literacy", "minPercent": 40 }, { "subject": "Any other additional subjects", "minPercent": 40 } ] },
        { "name": "BSc (Industrial Chemistry)", "aps": 24, "duration": "4 years", "description": "Industrial chemists usually work in chemical plants and laboratories across a broad range of industries, from chemical manufacturing, mining, building materials and paints/coatings through to paper, petroleum, plastics and advanced materials manufacturing. Offered at Arcadia Campus. Jobs: Industrial Chemist (R18 000–R80 000/month); Chemical Plant Chemist (R18 000–R75 000/month); Laboratory Chemist (R18 000–R75 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics", "minPercent": 60 }, { "subject": "Physical Sciences", "minPercent": 60 } ] },
        { "name": "Dip (Analytical Chemistry)", "aps": 21, "duration": "3 years", "description": "Prepares chemists, laboratory analysts and technologists, with opportunities for analytical chemistry graduates in laboratories, manufacturing and mining industries, research institutes, forensic departments and national science councils. Offered at Arcadia Campus. Jobs: Analytical Chemist (R20 000–R85 000/month); Laboratory Analyst (R14 000–R50 000/month); Technologist (R18 000–R70 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "Dip (Biotechnology)", "aps": 24, "duration": "3 years", "description": "Prepares biotechnologists or microbiologists to work in the industry or research labs, microbiology, waste management, beverage production, food production and research. Offered at Arcadia Campus. Jobs: Biotechnologist (R18 000–R80 000/month); Microbiologist (R18 000–R70 000/month); Laboratory Technician (R14 000–R49 000/month); Researcher (R20 000–R85 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 40 } ] },
        { "name": "Dip (Environmental Sciences)", "aps": 24, "duration": "3 years", "description": "Prepares graduates to be appointed as environmental officers or environmental technologists within numerous industries that deal with either managing negative changes on the biogeophysical environment or investigating existing impacts or potential impacts on the biogeophysical environment. Graduates may also be employed into a number of government departments or state bodies that deal with environmental impacts such as the Department of Environmental Affairs. Recommended subjects: Geography and Life Sciences. Offered at Arcadia Campus. Jobs: Environmental Officer (R16 000–R55 000/month); Environmental Technologist (R18 000–R70 000/month); Environmental Consultant (R18 000–R70 000/month); EIA Practitioner (R18 000–R75 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "Dip (Fire Technology) (Only offered to Fire and Rescue Services personnel)", "aps": 0, "duration": "3 years", "description": "For applicants already employed in Fire and Rescue Services: A National Senior Certificate with a bachelor's degree or diploma endorsement, or an equivalent qualification and three years' relevant work experience. HAZMAT Awareness, Fire Fighter I, HAZMAT Operational, and Fire Fighter II certificates required. Applicants must submit proof of employment (official letter from employer). Prepares fire fighters, fire prevention officers, fire safety officers, station officers, divisional officers, emergency services managers and officers in SANDF. Offered at Arcadia Campus. Jobs: Fire Fighter (R14 000–R45 000/month); Fire Safety Officer (R18 000–R55 000/month); Station Officer (R22 000–R65 000/month); Emergency Services Manager (R30 000–R95 000/month).", "requirements": [] },
        { "name": "Dip (Food Technology)", "aps": 24, "duration": "3 years", "description": "Prepares food technologists, quality controllers, researchers, developers of new products, with opportunities in food processing, canning, meat or fish factories, food quality and hygiene. Offered at Arcadia Campus. Jobs: Food Technologist (R18 000–R65 000/month); Quality Controller (R16 000–R55 000/month); Product Developer (R18 000–R70 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 }, { "subject": "Life Sciences", "minPercent": 40 } ] },
        { "name": "Dip (Geology)", "aps": 21, "duration": "3 years", "description": "Prepares engineering geologists, geological technicians or technologists, hydro-geological consultants, mining companies, Department of Minerals and Energy, Department of Water Affairs and Forestry professionals. Recommended subjects: Computer Applications Technology, Geography and/or Information Technology. Offered at Arcadia Campus. Jobs: Engineering Geologist (R22 000–R90 000/month); Geological Technician (R18 000–R70 000/month); Hydro-Geological Consultant (R22 000–R88 000/month); Mining Geologist (R26 000–R120 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "Dip (Industrial Physics)", "aps": 21, "duration": "3 years", "description": "Prepares photonics professionals (optical instrument technicians, lens-coating technicians, laser technicians, vacuum technicians, metrologists (optical), non-destructive testing technicians) and nuclear technologists (general nuclear technicians, radiation protection technicians, waste management technicians, radiation risk technicians, radioactive contamination risk technicians, vacuum technicians, non-destructive testing technicians, metrologists). Offered at Arcadia Campus. Jobs: Photonics Technician (R18 000–R70 000/month); Radiation Protection Technician (R20 000–R80 000/month); Optical Instrument Technician (R18 000–R70 000/month); Metrologist (R20 000–R75 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "Dip (Water Science and Technology)", "aps": 21, "duration": "3 years", "description": "Prepares water care technicians, water care technologists and process controllers. Recommended subjects: Life Sciences. Offered at Arcadia Campus. Jobs: Water Care Technician (R14 000–R55 000/month); Water Care Technologist (R20 000–R75 000/month); Process Controller (R16 000–R60 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 50 }, { "subject": "Mathematics OR Technical Mathematics", "minPercent": 50 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 50 } ] },
        { "name": "HCert (Resource and Waste Management)", "aps": 18, "duration": "1 year", "description": "Prepares water care technicians, water care technologists and process controllers. Pathway to Dip (Environmental Sciences). Offered at Arcadia Campus. Note: APS 18 with Mathematics or Technical Mathematics; APS 21 with Mathematical Literacy. Jobs: Water Care Technician (R14 000–R55 000/month); Water Care Technologist (R20 000–R75 000/month); Process Controller (R16 000–R60 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 40 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 40 } ] },
        { "name": "HCert (Water Treatment)", "aps": 18, "duration": "1 year", "description": "Prepares water care technicians, water care technologists and process controllers. Pathway to Dip (Water Science and Technology). Offered at Arcadia Campus. Note: APS 18 with Mathematics or Technical Mathematics; APS 21 with Mathematical Literacy. Jobs: Water Care Technician (R14 000–R55 000/month); Water Care Technologist (R20 000–R75 000/month); Process Controller (R16 000–R60 000/month).", "requirements": [ { "subject": "English Home Language OR English First Additional Language", "minPercent": 40 }, { "subject": "Mathematics OR Technical Mathematics OR Mathematical Literacy", "minPercent": 40 }, { "subject": "Physical Sciences OR Technical Sciences", "minPercent": 40 } ] }
