        { name: "Bachelor of Medical Sciences", aps: 24, duration: "3 years", description: "This three-year programme equips the learner with knowledge and skills in general pre-medical or basic sciences. The program's first year is common with the non-medical sciences offered by the Faculty of Natural Sciences. From year 2, the learner can choose a specific stream of interest (Physiology or Biochemistry). Jobs: Medical Scientist (R20 000–R80 000/month); Laboratory Researcher (R18 000–R70 000/month); Clinical Research Associate (R18 000–R70 000/month); Laboratory Manager (R22 000–R80 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 }, { subject: "Any other African Language", minPercent: 50 }, { subject: "Mathematics", minPercent: 50 }, { subject: "Physical Sciences", minPercent: 50 }, { subject: "Life Sciences", minPercent: 50 }, { subject: "Any other subject (excluding LO)", minPercent: 50 } ] },
        { name: "Bachelor of Medicine in Clinical Practice", aps: 24, duration: "3 years", description: "The general purpose of this three-year bachelor's degree is to train a competent, professional healthcare team member to function effectively as a Clinical Associate (CA) to assist with a defined scope of clinical procedures assisting district hospital doctors and working under their supervision. Jobs: Clinical Associate (R20 000–R70 000/month); Clinical Research Associate (R18 000–R65 000/month); Medical Practice Assistant (R18 000–R60 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 }, { subject: "Any other African Language", minPercent: 50 }, { subject: "Mathematics", minPercent: 50 }, { subject: "Physical Sciences", minPercent: 50 }, { subject: "Life Sciences", minPercent: 50 }, { subject: "Any other subject (excluding LO)", minPercent: 50 } ] },
        { name: "Bachelor of Nursing", aps: 24, duration: "4 years", description: "The qualification aims to produce competent professional nurse practitioners within various health service settings. The professional nurse will be qualified with a comprehensive scope that includes obstetric skills, mental health, and primary health care. Jobs: Professional Nurse (R18 000–R67 000/month); Midwife (R20 000–R70 000/month); Clinic Nurse (R16 000–R56 000/month); Nurse Manager (R28 000–R88 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 }, { subject: "Any other African Language", minPercent: 50 }, { subject: "Mathematics", minPercent: 50 }, { subject: "Physical Sciences", minPercent: 50 }, { subject: "Life Sciences", minPercent: 50 }, { subject: "Any other subject (excluding LO)", minPercent: 50 } ] },
        { name: "Bachelor of Health Sciences in Medical Orthotics and Prosthetics", aps: 24, duration: "4 years", description: "The qualification will produce a well-rounded learner who will be capable of practicing as an orthotic and prosthetic clinician. Medical Prosthetics is a profession that deals with replacing body limbs that are removed as a cause of accident, diseases or surgery. Jobs: Medical Orthotist and Prosthetist (R25 000–R85 000/month); Private Practice Owner (variable); Medical Representative (Orthopaedic Rehabilitation) (R18 000–R65 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 50 }, { subject: "Any other African Language", minPercent: 50 }, { subject: "Mathematics", minPercent: 50 }, { subject: "Physical Sciences", minPercent: 50 }, { subject: "Life Sciences", minPercent: 50 }, { subject: "Any other subject (excluding LO)", minPercent: 50 } ] },
        { name: "Bachelor of Medicine and Bachelor of Surgery (MBChB)", aps: 30, duration: "6 years", description: "This innovative medical programme provides the required knowledge, skills and attitudes to practice medicine in various settings using a PBL and a community-based approach. It will equip the learner to manage diverse health problems in individuals, families and communities. Jobs: Medical Doctor (after internship) (R35 000–R149 000/month); Medical Specialist (after postgraduate training) (R60 000–R200 000/month); Clinical Researcher (R25 000–R96 000/month); Public Health Officer (R22 000–R84 000/month).", requirements: [ { subject: "English Home Language OR English First Additional Language", minPercent: 60 }, { subject: "Any other African Language", minPercent: 60 }, { subject: "Mathematics", minPercent: 60 }, { subject: "Physical Sciences", minPercent: 60 }, { subject: "Life Sciences", minPercent: 60 }, { subject: "Any other subject (excluding LO)", minPercent: 60 } ] }
